sys_script_include.script:
var ERTriageRunAjax = Class.create();
ERTriageRunAjax.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
  T_ENCOUNTER: 'x_2206627_er_tri_0_encounter',
  T_ASSESSMENT: 'x_2206627_er_tri_0_triage_assessment',

  start: function() {
    if (!gs.hasRole('x_2206627_er_tri_0.triage_nurse'))
      return JSON.stringify({ ok: false, error: 'Not authorized' });

    var id = this.getParameter('sysparm_encounter');
    var e = new GlideRecord(this.T_ENCOUNTER);
    if (!e.get(id)) return JSON.stringify({ ok: false, error: 'Encounter not found' });
    if (e.getValue('triage_job_status') == 'running')
      return JSON.stringify({ ok: true, already: true });   // don't start twice

    e.setValue('triage_job_status', 'running');
    e.setValue('triage_job_message', 'Queued...');
    e.setWorkflow(false);
    e.update();

    gs.eventQueue('x_2206627_er_tri_0.retriage_requested', e, id, gs.getUserID());
    return JSON.stringify({ ok: true });
  },

  status: function() {
    var id = this.getParameter('sysparm_encounter');
    var e = new GlideRecord(this.T_ENCOUNTER);
    if (!e.get(id)) return JSON.stringify({ status: 'failed', message: 'Encounter not found' });

    var out = {
      status: e.getValue('triage_job_status') || 'idle',
      message: e.getValue('triage_job_message') || ''
    };
    if (out.status == 'done' && !e.current_assessment.nil()) {
      var a = new GlideRecord(this.T_ASSESSMENT);
      if (a.get(e.getValue('current_assessment'))) {
        out.assessment = a.getUniqueValue();
        out.suggested_esi = a.getValue('suggested_esi');
        out.rule_esi = a.getValue('rule_esi');
        out.llm_esi = a.getValue('llm_esi');
        out.rationale = a.getValue('ai_rationale');
        out.ai_available = a.getValue('ai_available');
      }
    }
    return JSON.stringify(out);
  },

  type: 'ERTriageRunAjax'
});
